	@Test
	void postNativeSuccessWithoutRevisionSettlementCannotAuthorizeReadyProvider(
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		try (Fixture fixture = Fixture.open(root)) {
			LmdbEvaluationStatistics old = (LmdbEvaluationStatistics) fixture.backing().getEvaluationStatistics();
			assertNull(old.estimatorRuntime().feedback(), "the facade was created before provider publication");
			fixture.releasePostReady();
			try (Compiled compiled = compile(fixture)) {
				assertTrue(compiled.owner.isCurrentForPhysicalCost());
				compiled.statistics.recordFilterOutcome(compiled.filter, 30L, 70L);
				assertNotNull(compiled.statistics.estimatorRuntime().learnedFilterEvidence(compiled.filter),
						"the ready provider contains the prior committed observation");
				LmdbEvaluationStrategy.bindExecutionSnapshot(old, compiled.source, null);
				boolean oldSeesReady = old.estimatorRuntime().feedback() != null;
				boolean oldSeesEvidence = old.estimatorRuntime().learnedFilterEvidence(compiled.filter) != null;
				TripleStore triples = fixture.backing().getTripleStore();
				long logicalBefore = triples.getDataRevision();
				long generationBefore = triples.getNativeCommitGeneration();
				IRI subject = VF.createIRI("urn:deferred-boundary:post-native");
				var object = VF.createLiteral("post-native");
				IllegalStateException injected = new IllegalStateException("injected after confirmed native success");
				triples.durableCommitBarrierForTesting = () -> {
					throw injected;
				};
				RuntimeException failure;
				try (var connection = fixture.repository.getConnection()) {
					connection.begin();
					connection.add(subject, PREDICATE, object);
					try {
						failure = assertThrows(RuntimeException.class, connection::commit);
					} finally {
						triples.durableCommitBarrierForTesting = null;
					}
				}
				Throwable cause = failure;
				while (cause != null && cause != injected) {
					cause = cause.getCause();
				}
				assertSame(injected, cause, "the original post-success failure must reach the caller");
				assertTrue(triples.getNativeCommitGeneration() > generationBefore);
				var receipt = triples.statementCommitReceiptAfter(generationBefore);
				assertNotNull(receipt, "the exact statement commit receipt is recorded");
				assertEquals(logicalBefore, triples.getDataRevision(),
						"the injected boundary precedes revision publication");
				assertNull(triples.currentWriterTransaction());
				assertEquals(0L, triples.writeTxn);
				try (ReceiptPair pair = admitPairAtReceipt(fixture, receipt)) {
					var source = pair.source();
					var owner = source.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
					var transaction = owner.pinnedReadTxn().orElseThrow();
					var dictionary = owner.pinnedValueSnapshot().orElseThrow();
					boolean current = owner.isCurrentForPhysicalCost();
					boolean committedRow;
					try (var rows = source.getStatements(subject, PREDICATE, object)) {
						committedRow = rows.hasNext();
					}
					LmdbEvaluationStrategy.bindExecutionSnapshot(old, source, null);
					boolean allowed = old.feedbackPublicationAllowed();
					boolean providerAfter = old.estimatorRuntime().feedback() != null;
					boolean evidenceAfter = old.estimatorRuntime().learnedFilterEvidence(compiled.filter) != null;
					Files.writeString(root.resolve("receipt-authority.txt"), "generationBefore=" + generationBefore
							+ " receipt=" + receipt + " logicalBefore=" + logicalBefore + " logicalAfter="
							+ triples.getDataRevision() + " sourceNative=" + transaction.nativeTransactionId()
							+ " sourceLogical=" + transaction.snapshotRevision() + " paired="
							+ dictionary.isPairedWith(transaction)
							+ " current=" + current + " committedRow=" + committedRow + " oldProviderBefore="
							+ oldSeesReady + " oldEvidenceBefore=" + oldSeesEvidence + " oldProviderAfter="
							+ providerAfter + " allowed=" + allowed + " evidenceAfter=" + evidenceAfter + "\n");
					assertTrue(dictionary.isPairedWith(transaction));
					assertTrue(transaction.nativeTransactionId() >= receipt.epoch(),
							"the source reaches the native receipt");
					assertTrue(committedRow, "this exact source reads the physically committed statement");
					assertTrue(current, "the store considers this exact paired source current");
					assertEquals(logicalBefore, transaction.snapshotRevision());
					assertTrue(oldSeesReady && oldSeesEvidence,
							"the old facade resolved the ready provider before failure");
					assertFalse(allowed, "an unsettled committed revision cannot authorize new feedback");
					assertFalse(evidenceAfter,
							"an unsettled committed revision cannot expose the old provider evidence");
				}
			}
		}
	}

