	@Test
	void postNativeSuccessRejectsFeedbackFromFreshPairedSource(@TempDir(cleanup = CleanupMode.NEVER) Path root)
			throws Exception {
		probePostNativeFeedbackAuthority(root, true);
	}

	private void probePostNativeFeedbackAuthority(Path root, boolean freshSource) throws Exception {
		try (Fixture fixture = Fixture.open(root)) {
			LmdbEvaluationStatistics old = (LmdbEvaluationStatistics) fixture.backing().getEvaluationStatistics();
			assertNull(old.estimatorRuntime().feedback(), "the facade was created before provider publication");
			fixture.releasePostReady();
			try (Compiled compiled = compile(fixture)) {
				compiled.statistics.recordFilterOutcome(compiled.filter, 30L, 70L);
				assertNotNull(compiled.statistics.estimatorRuntime().feedback(), "the actual paired provider is ready");
				var before = compiled.statistics.estimatorRuntime().learnedFilterEvidence(compiled.filter);
				assertNotNull(before, "the ready provider contains the prior committed observation");
				LmdbEvaluationStrategy.bindExecutionSnapshot(old, compiled.source, null);
				boolean oldReady = old.estimatorRuntime().feedback() != null;
				boolean oldEvidence = old.estimatorRuntime().learnedFilterEvidence(compiled.filter) != null;
				TripleStore triples = fixture.backing().getTripleStore();
				long logicalBefore = triples.getDataRevision();
				long generationBefore = triples.getNativeCommitGeneration();
				IRI subject = VF.createIRI("urn:deferred-boundary:post-native");
				var object = VF.createLiteral("post-native");
				IllegalStateException injected = new IllegalStateException("injected after confirmed native success");
				triples.durableCommitBarrierForTesting = () -> {
					throw injected;
				};
				RuntimeException failure;
				try (var connection = fixture.repository.getConnection()) {
					connection.begin();
					connection.add(subject, PREDICATE, object);
					try {
						failure = assertThrows(RuntimeException.class, connection::commit);
					} finally {
						triples.durableCommitBarrierForTesting = null;
					}
				}
				Throwable cause = failure;
				while (cause != null && cause != injected) {
					cause = cause.getCause();
				}
				assertSame(injected, cause, "the original post-success failure must reach the caller");
				assertTrue(triples.getNativeCommitGeneration() > generationBefore);
				var receipt = triples.statementCommitReceiptAfter(generationBefore);
				assertNotNull(receipt, "the exact statement commit receipt is recorded");
				assertEquals(logicalBefore, triples.getDataRevision(),
						"the injected boundary precedes revision publication");
				assertNull(triples.currentWriterTransaction());
				assertEquals(0L, triples.writeTxn);

				List<SailDataset> retained = new java.util.ArrayList<>();
				try {
					SailDatasetTripleTermSource selected = null;
					List<Long> admittedEpochs = new java.util.ArrayList<>();
					Set<TxnManager.Txn> admittedOwners = new HashSet<>();
					int attempts = Math.min(triples.getTxnManager().availableOrdinaryPermits(),
							fixture.backing().valueStore().getTxnManager().availableOrdinaryPermits()) - 4;
					while (selected == null && attempts-- > 0) {
						SailDataset dataset = fixture.backing()
								.getExplicitSailSource()
								.dataset(IsolationLevels.SNAPSHOT_READ);
						retained.add(dataset);
						var candidate = new SailDatasetTripleTermSource(fixture.store.getValueFactory(), dataset);
						var candidateOwner = candidate.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
						var candidateTxn = candidateOwner.pinnedReadTxn().orElseThrow();
						admittedEpochs.add(candidateTxn.nativeTransactionId());
						if (freshSource == (candidateTxn.nativeTransactionId() >= receipt.epoch())) {
							selected = candidate;
						} else if (!admittedOwners.add(candidateTxn)) {
							break;
						}
					}
					Files.writeString(root.resolve("admitted-epochs.txt"),
							"fresh=" + freshSource + " receipt=" + receipt
									+ " admitted=" + admittedEpochs + "\n");
					assertNotNull(selected, "ordinary admission must reach the requested side of the native receipt");
					var owner = selected.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
					var transaction = owner.pinnedReadTxn().orElseThrow();
					var dictionary = owner.pinnedValueSnapshot().orElseThrow();
					boolean current = owner.isCurrentForPhysicalCost();
					boolean row;
					try (var rows = selected.getStatements(subject, PREDICATE, object)) {
						row = rows.hasNext();
					}
					LmdbEvaluationStrategy.bindExecutionSnapshot(old, selected, null);
					boolean allowed = old.feedbackPublicationAllowed();
					boolean visible = old.estimatorRuntime().learnedFilterEvidence(compiled.filter) != null;
					long learnerRevisionBefore = fixture.learned().planningRevision();
					old.recordFilterOutcome(compiled.filter, 10L, 90L);
					long learnerRevisionAfter = fixture.learned().planningRevision();
					var after = old.estimatorRuntime().learnedFilterEvidence(compiled.filter);
					Files.writeString(root.resolve("receipt-authority-v2.txt"), "fresh=" + freshSource
							+ " receipt=" + receipt + " logicalBefore=" + logicalBefore + " logicalAfter="
							+ triples.getDataRevision() + " sourceNative=" + transaction.nativeTransactionId()
							+ " sourceLogical=" + transaction.snapshotRevision() + " sameStore="
							+ transaction.belongsTo(triples.getTxnManager()) + " paired="
							+ dictionary.isPairedWith(transaction)
							+ " current=" + current + " committedRow=" + row + " oldReadyBefore=" + oldReady
							+ " oldEvidenceBefore=" + oldEvidence + " allowed=" + allowed + " visible=" + visible
							+ " providerCountBefore=" + before.evidenceCount() + " providerCountAfter="
							+ (after == null ? "withheld" : after.evidenceCount()) + " learnerRevisionBefore="
							+ learnerRevisionBefore + " learnerRevisionAfter=" + learnerRevisionAfter
							+ " admitted=" + admittedEpochs + "\n");
					assertTrue(transaction.belongsTo(triples.getTxnManager()));
					assertTrue(dictionary.isPairedWith(transaction));
					assertEquals(logicalBefore, transaction.snapshotRevision());
					if (freshSource) {
						assertTrue(transaction.nativeTransactionId() >= receipt.epoch());
						assertTrue(row, "the fresh pair sees the committed statement");
					} else {
						assertTrue(transaction.nativeTransactionId() < receipt.epoch());
						assertFalse(row, "the older pair does not see the committed statement");
					}
					assertTrue(oldReady && oldEvidence, "the old facade resolved the ready provider before failure");
					if (after != null) {
						assertEquals(before.evidenceCount(), after.evidenceCount(),
								"an unsettled statement receipt must not publish a new provider observation");
					}
					assertEquals(learnerRevisionBefore, learnerRevisionAfter,
							"an unsettled statement receipt must not publish to the store-owned learner");
					assertFalse(allowed, "an unsettled statement receipt cannot authorize feedback");
					assertFalse(visible, "an unsettled statement receipt cannot expose learned provider evidence");
				} finally {
					for (int i = retained.size() - 1; i >= 0; i--) {
						retained.get(i).close();
					}
				}
			}
		}
	}

