	@Test
	void readyFacadeCannotRecordAfterItsSourceIsInvalidatedDuringProviderEntry(
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		probeProviderEntryRace(root, false);
	}

	private void probeProviderEntryRace(Path root, boolean deferredFacade) throws Exception {
		try (Fixture fixture = Fixture.open(root)) {
			LmdbEvaluationStatistics old = (LmdbEvaluationStatistics) fixture.backing().getEvaluationStatistics();
			assertNull(old.estimatorRuntime().feedback(), "the old facade predates provider readiness");
			fixture.releasePostReady();
			try (Compiled compiled = compile(fixture)) {
				LmdbEvaluationStatistics recorderFacade = deferredFacade ? old : compiled.statistics;
				if (deferredFacade) {
					LmdbEvaluationStrategy.bindExecutionSnapshot(old, compiled.source, null);
				}
				var provider = compiled.statistics.estimatorRuntime().filters();
				assertNotNull(provider, "the real ready provider must be present");
				assertSame(provider, recorderFacade.estimatorRuntime().filters(), "the facade must use that provider");
				assertTrue(recorderFacade.feedbackPublicationAllowed(), "the exact query source is initially current");
				compiled.statistics.recordFilterOutcome(compiled.filter, 30L, 70L);
				var before = provider.estimateLearnedSurface(compiled.filter);
				assertNotNull(before);
				assertEquals(100L, before.evidenceCount());
				TripleStore triples = fixture.backing().getTripleStore();
				long revisionBefore = triples.getDataRevision();
				long generationBefore = triples.getNativeCommitGeneration();
				IRI subject = VF.createIRI("urn:deferred-boundary:race-subject");
				var object = VF.createLiteral("race-object");
				AtomicReference<Throwable> failure = new AtomicReference<>();
				Thread recorder = new Thread(() -> {
					try {
						recorderFacade.recordFilterOutcome(compiled.filter, 10L, 90L);
					} catch (Throwable exception) {
						failure.set(exception);
					}
				}, "deferred-provider-race-recorder");
				recorder.setDaemon(true);
				org.eclipse.rdf4j.sail.lmdb.LmdbFilterSelectivityStats.LearnedSurfaceEstimate cleared = null;
				java.lang.management.ThreadInfo blocked = null;
				try {
					synchronized (provider) {
						recorder.start();
						long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
						while (recorder.isAlive() && System.nanoTime() < deadline) {
							var info = java.lang.management.ManagementFactory.getThreadMXBean()
									.getThreadInfo(recorder.threadId(), 40);
							if (info != null && info.getThreadState() == Thread.State.BLOCKED
									&& info.getLockOwnerId() == Thread.currentThread().threadId()
									&& info.getLockInfo().getIdentityHashCode() == System.identityHashCode(provider)) {
								blocked = info;
								break;
							}
							Thread.onSpinWait();
						}
						assertNotNull(blocked, "the recorder must reach the actual provider monitor");
						assertTrue(
								java.util.Arrays.stream(blocked.getStackTrace())
										.anyMatch(frame -> frame.getClassName()
												.equals(LmdbFilterSelectivityStats.class.getName())
												&& frame.getMethodName().equals("recordFilterOutcome")),
								"the blocked stack must be the provider feedback write");
						assertTrue(recorderFacade.feedbackPublicationAllowed(),
								"the recorder passed the source check before entering the monitor");
						try (var connection = fixture.repository.getConnection()) {
							connection.begin();
							connection.add(subject, PREDICATE, object);
							connection.commit();
						}
						cleared = provider.estimateLearnedSurface(compiled.filter);
						assertNull(cleared, "the real committed mutation resets the provider before release");
						assertNotNull(triples.statementCommitReceiptAfter(generationBefore));
						assertTrue(triples.getDataRevision() > revisionBefore);
					}
				} finally {
					recorder.join(TimeUnit.SECONDS.toMillis(30));
					if (recorder.isAlive()) {
						fixture.retainStore = true;
						throw new IllegalStateException("recorder retained with fixture " + root);
					}
				}
				assertNull(failure.get(), "the recorder finishes without failure");
				var after = provider.estimateLearnedSurface(compiled.filter);
				boolean row;
				try (var connection = fixture.repository.getConnection()) {
					row = connection.hasStatement(subject, PREDICATE, object, false);
				}
				Files.writeString(root.resolve("provider-entry-race.txt"), "deferred=" + deferredFacade
						+ " blocked=" + blocked + " before=" + before.evidenceCount() + " afterCommit=" + cleared
						+ " afterRecorder=" + after + " row=" + row + " oldCurrent="
						+ compiled.owner.isCurrentForPhysicalCost() + " revisionBefore=" + revisionBefore
						+ " revisionAfter=" + triples.getDataRevision() + "\n");
				assertTrue(row, "the new statement must actually be committed");
				assertFalse(compiled.owner.isCurrentForPhysicalCost(), "the query source is stale after the commit");
				assertNull(after, "an invalidated source must not repopulate the provider after its commit reset");
			}
		}
	}

