	@Test
	void nestedProviderTargetDeclinesFeedbackWhileARealWriterOwnsTheNativeBarrier(
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		try (Fixture fixture = Fixture.open(root)) {
			fixture.releasePostReady();
			try (Compiled compiled = compile(fixture)) {
				var filters = compiled.statistics.estimatorRuntime().filters();
				assertNotNull(filters);
				RuntimeFeedbackTarget target = completedProviderTarget(fixture, compiled, true);
				var feedback = compiled.statistics.estimatorRuntime().feedback();
				assertNotNull(feedback);
				List<LmdbPlanDecisionCache.ExecutionObservation> observations = new java.util.ArrayList<>();
				feedback.setPlanExecutionObserver(observations::add);
				compiled.statistics.recordFilterOutcome(compiled.filter, 30L, 70L);
				long evidenceBefore = filters.estimateLearnedSurface(compiled.filter).evidenceCount();
				long learnedBefore = fixture.learned().planningRevision();
				TripleStore triples = fixture.backing().getTripleStore();
				CountDownLatch entered = new CountDownLatch(1);
				CountDownLatch release = new CountDownLatch(1);
				AtomicReference<Throwable> writerFailure = new AtomicReference<>();
				AtomicReference<Throwable> recorderFailure = new AtomicReference<>();
				IRI subject = VF.createIRI("urn:deferred-boundary:held-native-writer");
				var object = VF.createLiteral("held-native-writer");
				triples.beforePhysicalCommitForTest = () -> {
					entered.countDown();
					try {
						if (!release.await(30, TimeUnit.SECONDS)) {
							throw new IllegalStateException("test did not release the native commit");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new IllegalStateException(interrupted);
					}
				};
				Thread writer = commitThread(fixture, subject, object, writerFailure);
				Thread recorder = new Thread(() -> {
					try {
						feedback.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
					} catch (Throwable failure) {
						recorderFailure.set(failure);
					}
				}, "nested-feedback-with-held-native-writer");
				recorder.setDaemon(true);
				try {
					writer.start();
					assertTrue(entered.await(20, TimeUnit.SECONDS), "the real commit reached its held native barrier");
					assertTrue(triples.getTxnManager().lockManager().isWriterActive());
					recorder.start();
					recorder.join(TimeUnit.SECONDS.toMillis(20));
					assertFalse(recorder.isAlive(), "feedback must decline without waiting for the native writer");
					assertNull(recorderFailure.get());
					assertEquals(evidenceBefore, filters.estimateLearnedSurface(compiled.filter).evidenceCount(),
							"declined target publication must not mutate its filter cells");
					assertEquals(learnedBefore, fixture.learned().planningRevision(),
							"declined target publication must not mutate its nested learned outcome");
					assertEquals(0, observations.size(), "a barrier-declined target must not train its plan observer");
				} finally {
					release.countDown();
					writer.join(TimeUnit.SECONDS.toMillis(30));
					recorder.join(TimeUnit.SECONDS.toMillis(30));
					triples.beforePhysicalCommitForTest = null;
					if (writer.isAlive() || recorder.isAlive()) {
						fixture.retainStore = true;
						throw new IllegalStateException("native contention threads retained at " + root);
					}
					target.release();
				}
				assertNull(writerFailure.get());
				try (var connection = fixture.repository.getConnection()) {
					assertTrue(connection.hasStatement(subject, PREDICATE, object, false));
				}
				Files.writeString(root.resolve("held-native-writer.txt"), "evidenceBefore=" + evidenceBefore
						+ " learnedBefore=" + learnedBefore + " publicationDeclined=true committedRow=true\n");
			}
		}
	}

	@Test
	void nestedProviderPublicationAndConcurrentCommitSettleWithoutLockInversion(
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		try (Fixture fixture = Fixture.open(root)) {
			fixture.releasePostReady();
			try (Compiled compiled = compile(fixture)) {
				RuntimeFeedbackTarget target = completedProviderTarget(fixture, compiled);
				var learner = fixture.learned();
				AtomicReference<Throwable> writerFailure = new AtomicReference<>();
				AtomicReference<Throwable> recorderFailure = new AtomicReference<>();
				IRI subject = VF.createIRI("urn:deferred-boundary:nested-feedback-writer");
				var object = VF.createLiteral("nested-feedback-writer");
				Thread writer = commitThread(fixture, subject, object, writerFailure);
				Thread recorder = new Thread(() -> {
					try {
						target.publish(true);
					} catch (Throwable failure) {
						recorderFailure.set(failure);
					}
				}, "nested-provider-learner-recorder");
				recorder.setDaemon(true);
				java.lang.management.ThreadInfo blocked = null;
				java.lang.management.ThreadInfo competing = null;
				try {
					synchronized (learner) {
						recorder.start();
						long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
						while (recorder.isAlive() && System.nanoTime() < deadline) {
							var info = java.lang.management.ManagementFactory.getThreadMXBean()
									.getThreadInfo(recorder.threadId(), 64);
							if (info != null && info.getThreadState() == Thread.State.BLOCKED
									&& info.getLockOwnerId() == Thread.currentThread().threadId()
									&& info.getLockInfo().getIdentityHashCode() == System.identityHashCode(learner)) {
								blocked = info;
								break;
							}
							Thread.onSpinWait();
						}
						assertNotNull(blocked, "the provider publication must reach its actual nested learner monitor");
						assertTrue(java.util.Arrays.stream(blocked.getStackTrace())
								.anyMatch(
										frame -> frame.getClassName().equals(LmdbOperatorFeedbackStats.class.getName())
												&& frame.getMethodName().equals("publish")));
						writer.start();
						deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
						while (writer.isAlive() && System.nanoTime() < deadline) {
							var info = java.lang.management.ManagementFactory.getThreadMXBean()
									.getThreadInfo(writer.threadId(), 64);
							if (info != null && java.util.Arrays.stream(info.getStackTrace())
									.anyMatch(frame -> frame.getClassName()
											.equals(
													org.eclipse.rdf4j.common.concurrent.locks.StampedLongAdderLockManager.class
															.getName())
											&& frame.getMethodName().equals("writeLock"))) {
								competing = info;
								break;
							}
							Thread.onSpinWait();
						}
						assertNotNull(competing, "the real commit must compete for a held native read barrier");
					}
				} finally {
					recorder.join(TimeUnit.SECONDS.toMillis(30));
					writer.join(TimeUnit.SECONDS.toMillis(30));
					if (writer.isAlive() || recorder.isAlive()) {
						fixture.retainStore = true;
						throw new IllegalStateException("nested publication threads retained at " + root);
					}
					target.release();
				}
				assertNull(recorderFailure.get());
				assertNull(writerFailure.get());
				try (var connection = fixture.repository.getConnection()) {
					assertTrue(connection.hasStatement(subject, PREDICATE, object, false));
				}
				assertFalse(compiled.owner.isCurrentForPhysicalCost());
				Files.writeString(root.resolve("nested-provider-commit.txt"), "recorder=" + blocked
						+ " writer=" + competing + " bothSettled=true committedRow=true\n");
			}
		}
	}

	private static Thread commitThread(Fixture fixture, IRI subject, org.eclipse.rdf4j.model.Value object,
			AtomicReference<Throwable> failure) {
		Thread writer = new Thread(() -> {
			try (var connection = fixture.repository.getConnection()) {
				connection.begin();
				connection.add(subject, PREDICATE, object);
				connection.commit();
			} catch (Throwable problem) {
				failure.set(problem);
			}
		}, "real-nested-feedback-commit");
		writer.setDaemon(true);
		return writer;
	}

	@ParameterizedTest
	@EnumSource(ObserverBoundary.class)
	void planObserverReceivesOnlyCurrentAppliedTargetsAndRunsOutsideNativeBarriers(ObserverBoundary boundary,
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		try (Fixture fixture = Fixture.open(root)) {
			fixture.releasePostReady();
			try (Compiled compiled = compile(fixture)) {
				RuntimeFeedbackTarget target = completedProviderTarget(fixture, compiled, true);
				var feedback = compiled.statistics.estimatorRuntime().feedback();
				assertNotNull(feedback);
				List<LmdbPlanDecisionCache.ExecutionObservation> observations = new java.util.ArrayList<>();
				AtomicBoolean observerCommitted = new AtomicBoolean();
				IRI firstSubject = VF.createIRI("urn:deferred-boundary:before-target-commit");
				IRI observerSubject = VF.createIRI("urn:deferred-boundary:observer-commit");
				var object = VF.createLiteral("observer-control");
				feedback.setPlanExecutionObserver(observation -> {
					observations.add(observation);
					assertFalse(fixture.backing().getTripleStore().getTxnManager().lockManager().isReaderActive(),
							"the observer callback must not inherit native triple read barriers");
					assertFalse(fixture.backing().valueStore().getTxnManager().lockManager().isReaderActive(),
							"the observer callback must not inherit native dictionary read barriers");
					try (var connection = fixture.repository.getConnection()) {
						connection.add(observerSubject, PREDICATE, object);
					}
					observerCommitted.set(true);
				});
				var descriptor = (LmdbRuntimeFeedbackDescriptor) target.contract().descriptor();
				RuntimeFeedbackContract firstContract = target.contract()
						.withDescriptor(new LmdbRuntimeFeedbackDescriptor(null, null, descriptor.logicalKey(),
								descriptor.applicability(), descriptor.physicalKey()));
				RuntimeFeedbackTarget first = new RuntimeFeedbackAccumulator(firstContract,
						new RuntimeFeedbackAccumulator.Destination() {
							@Override
							public void publish(InvocationAggregateView observation) {
								if (boundary == ObserverBoundary.COMMIT_BEFORE_TARGET) {
									try (var connection = fixture.repository.getConnection()) {
										connection.add(firstSubject, PREDICATE, object);
									}
								}
							}

							@Override
							public void release() {
							}
						});
				first.open();
				first.close(1L, 1d, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
						EvaluationStatistics.TerminationClassification.EXHAUSTED);
				compiled.statistics.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { first, target }, 2,
						true);
				Files.writeString(root.resolve("observer-authority.txt"), "boundary=" + boundary
						+ " observations=" + observations.size() + " observerCommitted=" + observerCommitted.get()
						+ "\n");
				if (boundary == ObserverBoundary.COMMIT_BEFORE_TARGET) {
					try (var connection = fixture.repository.getConnection()) {
						assertTrue(connection.hasStatement(firstSubject, PREDICATE, object, false));
					}
					assertFalse(compiled.owner.isCurrentForPhysicalCost());
					assertEquals(0, observations.size(), "a source-rejected target must not train the plan observer");
				} else {
					assertEquals(1, observations.size(), "the applied current target supplies one plan observation");
					assertTrue(observerCommitted.get(),
							"the observer can reentrantly commit after native barriers release");
				}
			}
		}
	}

