	private static RuntimeFeedbackTarget completedProviderTarget(Fixture fixture, Compiled compiled) {
		return completedProviderTarget(fixture, compiled, false);
	}

	private static RuntimeFeedbackTarget completedProviderTarget(Fixture fixture, Compiled compiled,
			boolean planToken) {
		long revision = fixture.backing().getTripleStore().getDataRevision();
		LogicalLearningKey logical = LogicalLearningKey.of("filter", "condition", "children", "predicates",
				"v0", "none", "bag", "default");
		LearningApplicability applicability = new LearningApplicability(1L, 0L, "unconditional", revision, revision,
				1L);
		PhysicalResidualKey physical = PhysicalResidualKey.of("filter", "statement-pattern", "spoc", "single",
				"none", "none", "none", "bound");
		RuntimeFeedbackContract.PredictionVector prediction = new RuntimeFeedbackContract.PredictionVector(
				1d, 1d, 1d, 1d, 0d, 1d, 0d, 0d, 0d, 0d, 0d, 0d);
		RuntimeFeedbackContract contract = new RuntimeFeedbackContract(
				new LmdbRuntimeFeedbackDescriptor(null, null, logical, applicability, physical), prediction, prediction,
				1d, 1d, 1d, Double.POSITIVE_INFINITY, RuntimeFeedbackContract.SemanticKind.ORDINARY,
				RuntimeFeedbackContract.Algorithm.STREAMING_CORRELATED, RuntimeFeedbackContract.Access.EXACT_LOOKUP,
				physical.hashCode(), revision, revision, 1L,
				RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL
						| RuntimeFeedbackContract.ADMIT_FILTER);
		if (planToken) {
			var family = new LmdbPlanDecisionCache.PlanFamilyKey("family", "dataset", "bindings", "unordered",
					"none", revision, revision, "environment");
			var token = new LmdbPlanDecisionCache.PlanExecutionToken(family, 7L, 11L, 13L, 17L, true);
			contract = contract.withDescriptor(
					((LmdbRuntimeFeedbackDescriptor) contract.descriptor()).withPlanExecutionToken(token));
		}
		compiled.filter.setRuntimeFeedbackContract(contract);
		compiled.filter.setCostFeedbackTrackingEnabled(true);
		RuntimeFeedbackTarget target = compiled.statistics.resolveRuntimeFeedbackTarget(compiled.filter, contract);
		assertTrue(target.active(), "the actual source must bind a provider target with nested destinations");
		target.open(EmptyBindingSet.getInstance());
		target.close(20L, 100d, 100L, 0L, 100L, 0L, 0L, 0L, 0L, 0L,
				EvaluationStatistics.TerminationClassification.EXHAUSTED);
		target.recordFilter(20L, 80L);
		target.recordActualPhysicalImplementation(contract.physicalImplementationId());
		return target;
	}

	private record ReceiptPair(List<SailDataset> retained, SailDatasetTripleTermSource source)
			implements AutoCloseable {
		@Override
		public void close() {
			for (SailDataset dataset : retained.reversed()) {
				dataset.close();
			}
		}
	}

	private static ReceiptPair admitPairAtReceipt(Fixture fixture, TripleStore.StatementCommitReceipt receipt)
			throws Exception {
		List<SailDataset> retained = new java.util.ArrayList<>();
		try {
			int attempts = Math.min(fixture.backing().getTripleStore().getTxnManager().availableOrdinaryPermits(),
					fixture.backing().valueStore().getTxnManager().availableOrdinaryPermits()) - 4;
			while (attempts-- > 0) {
				SailDataset dataset = fixture.backing().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
				retained.add(dataset);
				var source = new SailDatasetTripleTermSource(fixture.store.getValueFactory(), dataset);
				var owner = source.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
				if (owner.pinnedReadTxn().orElseThrow().nativeTransactionId() >= receipt.epoch()) {
					return new ReceiptPair(retained, source);
				}
			}
			throw new AssertionError("ordinary reader admission did not reach the actual statement receipt");
		} catch (Exception | Error failure) {
			for (SailDataset dataset : retained.reversed()) {
				try {
					dataset.close();
				} catch (RuntimeException | Error cleanup) {
					failure.addSuppressed(cleanup);
				}
			}
			throw failure;
		}
	}

	private static boolean readsCommittedRowAtReceipt(Fixture fixture, IRI subject,
			org.eclipse.rdf4j.model.Value object, TripleStore.StatementCommitReceipt receipt, Path evidence)
			throws Exception {
		TripleStore triples = fixture.backing().getTripleStore();
		List<SailDataset> retained = new java.util.ArrayList<>();
		List<Long> admittedEpochs = new java.util.ArrayList<>();
		Set<TxnManager.Txn> admittedOwners = new HashSet<>();
		boolean row = false;
		boolean freshPair = false;
		try {
			int attempts = Math.min(triples.getTxnManager().availableOrdinaryPermits(),
					fixture.backing().valueStore().getTxnManager().availableOrdinaryPermits()) - 4;
			while (!freshPair && attempts-- > 0) {
				SailDataset dataset = fixture.backing().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
				retained.add(dataset);
				var source = new SailDatasetTripleTermSource(fixture.store.getValueFactory(), dataset);
				var owner = source.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
				var transaction = owner.pinnedReadTxn().orElseThrow();
				var dictionary = owner.pinnedValueSnapshot().orElseThrow();
				admittedEpochs.add(transaction.nativeTransactionId());
				if (transaction.nativeTransactionId() >= receipt.epoch()) {
					assertTrue(transaction.belongsTo(triples.getTxnManager()));
					assertTrue(dictionary.isPairedWith(transaction));
					freshPair = true;
					try (var rows = source.getStatements(subject, PREDICATE, object)) {
						row = rows.hasNext();
					}
				} else if (!admittedOwners.add(transaction)) {
					break;
				}
			}
		} finally {
			for (int i = retained.size() - 1; i >= 0; i--) {
				retained.get(i).close();
			}
		}
		Files.writeString(evidence, "receipt=" + receipt + " admitted=" + admittedEpochs + " fresh="
				+ freshPair + " row=" + row + "\n");
		assertTrue(freshPair, "ordinary admission must reach a paired reader at or after the receipt");
		return row;
	}

	@ParameterizedTest
	@EnumSource(Fate.class)
	void realDirtyPublicationWithholdsAnExistingPairsEvidenceUntilItsFate(Fate fate,
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		try (Fixture fixture = Fixture.open(root)) {
			fixture.releasePostReady();
			try (Compiled compiled = compile(fixture)) {
				try (var rows = compiled.step.evaluate(EmptyBindingSet.getInstance())) {
					int count = 0;
					while (rows.hasNext()) {
						rows.next();
						count++;
					}
					assertEquals(32, count);
				}
				FilterPassEstimate before = compiled.statistics.estimateFilterPass(compiled.filter);
				assertLearnedOnce(before);
				assertTrue(compiled.owner.isCurrentForPhysicalCost());
				long beforeRevision = fixture.backing().getTripleStore().getDataRevision();
				CountDownLatch staged = new CountDownLatch(1);
				CountDownLatch release = new CountDownLatch(1);
				CountDownLatch finished = new CountDownLatch(1);
				AtomicReference<Throwable> writerFailure = new AtomicReference<>();
				AtomicReference<Boolean> pending = new AtomicReference<>();
				AtomicBoolean permitCommit = new AtomicBoolean();
				Thread writer = new Thread(() -> {
					Object writerOwner = new Object();
					try (SailSource source = fixture.backing().getExplicitSailSource(writerOwner);
							SailSource.PublicationScope publication = (SailSource.PublicationScope) source
									.beginPublication(writerOwner)) {
						boolean acceptedRelease = false;
						try (SailSink sink = source.sink(IsolationLevels.READ_COMMITTED)) {
							sink.approve(VF.createIRI("urn:deferred-boundary:s:1"), PREDICATE,
									VF.createLiteral("hit:0"), null);
							sink.flush();
							pending.set(fixture.backing().getTripleStore().hasPendingTripleMutation());
							staged.countDown();
							acceptedRelease = release.await(30, TimeUnit.SECONDS);
							if (!acceptedRelease) {
								throw new IllegalStateException("test did not release the native publication owner");
							}
						} finally {
							if (!acceptedRelease || !permitCommit.get() || fate == Fate.ROLLBACK) {
								publication.fail();
							}
						}
					} catch (Throwable failure) {
						writerFailure.set(failure);
					} finally {
						staged.countDown();
						finished.countDown();
					}
				}, "deferred-filter-publication-owner");
				writer.setDaemon(true);
				boolean sourceCurrentDuring;
				FilterPassEstimate during;
				boolean observedBeforeRelease;
				try {
					writer.start();
					assertTrue(staged.await(30, TimeUnit.SECONDS),
							"the actual publication must reach its staged boundary");
					assertNull(writerFailure.get(), "the writer must reach the intended boundary");
					assertEquals(Boolean.TRUE, pending.get(), "the native writer must contain a statement mutation");
					sourceCurrentDuring = compiled.owner.isCurrentForPhysicalCost();
					during = compiled.statistics.estimateFilterPass(compiled.filter);
					observedBeforeRelease = finished.getCount() == 1;
					permitCommit.set(observedBeforeRelease);
				} finally {
					release.countDown();
					boolean settled;
					try {
						settled = finished.await(30, TimeUnit.SECONDS);
					} catch (InterruptedException interrupted) {
						fixture.retainStore = true;
						RETAINED.add(fixture.store);
						Thread.currentThread().interrupt();
						throw interrupted;
					}
					if (!settled) {
						fixture.retainStore = true;
						RETAINED.add(fixture.store);
						throw new IllegalStateException("publication owner retained with fixture " + root + " "
								+ List.of(writer.getStackTrace()));
					}
				}
				assertNull(writerFailure.get(), "the publication owner must settle normally");
				long afterRevision = fixture.backing().getTripleStore().getDataRevision();
				boolean added;
				try (var connection = fixture.repository.getConnection()) {
					added = connection.hasStatement(VF.createIRI("urn:deferred-boundary:s:1"), PREDICATE,
							VF.createLiteral("hit:0"), false);
				}
				FilterPassEstimate after = estimateFromNewPair(fixture, compiled.filter);
				Files.writeString(root.resolve("publication-boundary.txt"), "fate=" + fate + " pending="
						+ pending.get() + " observedBeforeRelease=" + observedBeforeRelease + " sourceCurrentDuring="
						+ sourceCurrentDuring + " during=" + during.getSource() + " revision=" + beforeRevision + "->"
						+ afterRevision + " added=" + added + " after=" + after.getSource() + " afterEvidence="
						+ after.getEvidenceCount() + "\n");
				assertTrue(observedBeforeRelease, "the estimate must be observed while the dirty publication is held");
				assertFalse(sourceCurrentDuring, "the exact old pair cannot certify active publication");
				assertNotLearned(during);
				if (fate == Fate.ROLLBACK) {
					assertFalse(added, "the staged row was really rolled back");
					assertEquals(beforeRevision, afterRevision);
					assertLearnedOnce(after);
				} else {
					assertTrue(added, "the staged row was really committed");
					assertTrue(afterRevision > beforeRevision);
					assertNotLearned(after);
				}
			}
		}
	}

